import json, glob, math
H = glob.glob("/mnt/evox2/large/work/AI/freetoken/bfcl/runs/gsq-hip-A-on-*")[0]
S = glob.glob("/home/luwei/work/AI/bfcl/runs/strata-gsq-A-on-*think1")[0]
flat = lambda x: [z for y in x for z in flat(y)] if isinstance(x, list) else [x]
def mc(b, c):
    n = b + c; return min(1.0, 2 * sum(math.comb(n, k) for k in range(min(b, c) + 1)) / 2**n)
def res(run, cat):
    f = glob.glob(run + f"/result/**/BFCL_v4_multi_turn_{cat}_result.json", recursive=True)[0]
    return {json.loads(l)["id"]: json.loads(l) for l in open(f, encoding="utf-8-sig") if l.strip()}
def ok(run, cat):
    f = glob.glob(run + f"/score/**/BFCL_v4_multi_turn_{cat}_score.json", recursive=True)[0]
    bad = {json.loads(l)["id"] for l in list(open(f, encoding="utf-8-sig"))[1:] if l.strip()}
    return {f"multi_turn_{cat}_{i}" for i in range(200)} - bad
B = C = 0
for cat in ("base", "miss_param"):
    h, s = ok(H, cat), ok(S, cat); b, c = len(h - s), len(s - h); B += b; C += c
