    print(f"{cat:10s} Halo {len(h)/2:.1f}  Strata {len(s)/2:.1f} | only Halo {b}, only Strata {c}, McNemar p {mc(b, c):.3f} | "
          f"Strata refused {len(refused)}, of which Halo got right {len(refused & h)}")
    for name, run in (("Halo", H), ("Strata", S)):
        r = res(run, cat); lat = calls = out = 0
        for x in r.values():
            if "latency" not in x: continue
            ls = flat(x["latency"]); lat += sum(ls); calls += len(ls); out += sum(flat(x["output_token_count"]))
        print(f"    {name:7s} {lat/len(r):5.1f} s/entry, {calls/len(r):4.1f} calls/entry, {lat/calls:5.2f} s/call, {out/calls:4.0f} tok/call")
print(f"both: only Halo {B}, only Strata {C}, McNemar p {mc(B, C):.4f}")
EOF

